use std::fs

fn is_int(t: string) -> bool {
    let cs: Vec<char> = t.chars().collect()
    let n: int = cs.len() as int
    let start = if n > 0 && cs[0] == '-' { 1 } else { 0 }
    if start >= n {
        return false
    }
    let mut i = start
    while i < n {
        if cs[i] < '0' || cs[i] > '9' {
            return false
        }
        i += 1
    }
    true
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    let mut err = ""
    for t in line.split(" ") {
        if t == "" {
            continue
        }
        if t == "+" || t == "-" || t == "*" || t == "/" {
            let n: int = st.len() as int
            if n < 2 {
                err = "error: underflow"
                break
            }
            let b = st[n - 1]
            let a = st[n - 2]
            st.pop()
            st.pop()
            if t == "/" && b == 0 {
                err = "error: divzero"
                break
            }
            if t == "+" {
                st.push(a + b)
            } else if t == "-" {
                st.push(a - b)
            } else if t == "*" {
                st.push(a * b)
            } else {
                st.push(a / b)
            }
        } else if is_int(t) {
            let v: int = t.parse::<int>().unwrap_or(0)
            st.push(v)
        } else {
            err = "error: token"
            break
        }
    }
    if err != "" {
        err
    } else if st.len() != 1 {
        "error: leftover"
    } else {
        "${st[0]}"
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" {
            continue
        }
        println(eval(line.trim()))
    }
}

