    let mut i = start
    while i < n {
        if cs[i] < '0' || cs[i] > '9' {
            return false
        }
        i += 1
    }
    true
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split(" ") {
        if t == "" {
            continue
        }
        if t == "+" || t == "-" || t == "*" || t == "/" {
            let n: int = st.len() as int
            if n < 2 {
                return "error: underflow"
            }
            let b = st[n - 1]
            let a = st[n - 2]
            st.pop()
            st.pop()
            if t == "+" {
                st.push(a + b)
            } else if t == "-" {
                st.push(a - b)
            } else if t == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else if is_int(t) {
            let v: int = t.parse::<int>().unwrap_or(0)
            st.push(v)
        } else {
            return "error: token"
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    "${st[0]}"
}

